}

solution:
function cosine(a, b) {
  let dab = 0;
  let daa = 0;
  let dbb = 0;
  for (let i = 0; i < a.length; i++) {
    dab += a[i] * b[i];
    daa += a[i] * a[i];
    dbb += b[i] * b[i];
  }
  const na = Math.sqrt(daa);
  const nb = Math.sqrt(dbb);
  if (na === 0 || nb === 0) return 0;
  return dab / (na * nb);
}

