}

solution:
function gradStep(w, b, xs, ys, lr) {
  const n = xs.length;
  if (n === 0) return [w, b];
  let dw = 0;
  let db = 0;
  for (let i = 0; i < n; i++) {
    const err = w * xs[i] + b - ys[i];
    dw += err * xs[i];
    db += err;
  }
  dw = (2 / n) * dw;
  db = (2 / n) * db;
  return [w - lr * dw, b - lr * db];
}

