solution:
function matmul(a, b) {
  const n = a.length;
  if (n === 0) return [];
  const m = b.length;
  const p = b[0].length;
  const c = [];
  for (let i = 0; i < n; i++) {
    const row = [];
    for (let j = 0; j < p; j++) {
      let s = 0;
      for (let k = 0; k < m; k++) {
        s += a[i][k] * b[k][j];
      }
      row.push(s);
    }
    c.push(row);
  }
  return c;
}

