  let total = 0;
  for (const c of calls) {
    const p = prices[c.model];
    if (!p) continue;
    total += (c.input * p.input) / 1000000 + (c.output * p.output) / 1000000;
  }
  return Math.round(total * 1000000) / 1000000;
}

