function trimHistory(messages, limit) {
  const kept = [];
  let total = 0;
  for (let i = messages.length - 1; i >= 0; i--) {
    const cost = Math.ceil(messages[i].content.length / 4) + 4;
    if (total + cost > limit) break;
    total += cost;
    kept.unshift(messages[i]);
  }
  return kept;
}

