solution:
function evalExact(predictions, references) {
  const norm = (s) => s.toLowerCase().replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' ').trim();
  if (predictions.length === 0) return 0;
  let hit = 0;
  for (let i = 0; i < predictions.length; i++) {
    if (norm(predictions[i]) === norm(references[i])) hit++;
  }
  return hit / predictions.length;
}

