}

solution:
function runAgent(script, tools) {
  const has = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
  const transcript = [];
  for (const step of script) {
    if ('final' in step) {
      transcript.push('final: ' + step.final);
      return transcript;
    }
    if (!has(tools, step.action)) {
      transcript.push('error: unknown tool ' + step.action);
    } else if (!has(tools[step.action], step.input)) {
      transcript.push('error: no result for ' + step.input);
    } else {
      transcript.push(tools[step.action][step.input]);
    }
  }
  return transcript;
}
